# -*- coding: utf-8 -*-
# 追加 时态（topicId=11）100 题到 english-paper-1000.js（一次性脚本，幂等）
import io

def esc(s):
    return (s.replace('\\', '\\\\').replace('"', '\\"')
             .replace('\n', '\\n'))

qs = []
def fill(i, q, ans, why):
    qs.append('    { id: "p1000-%03d", subject: "english", module: "paper1000", topicId: 11, type: "fill",\n      q: "%s",\n      ansText: "%s",\n      why: "%s",\n      source: "语法1000题·时态" }' % (i, esc(q), esc(ans), esc(why)))

def cho(i, q, o, a, why):
    opts = ", ".join('"%s"' % esc(x) for x in o)
    qs.append('    { id: "p1000-%03d", subject: "english", module: "paper1000", topicId: 11, type: "choice",\n      q: "%s",\n      o: [%s], a: %d,\n      why: "%s",\n      source: "语法1000题·时态" }' % (i, esc(q), opts, a, esc(why)))

cho(671, "—______ you at school last night?\n—No, I ______ at home.", ["Was; was","Were; were","Were; was","Was; were"], 2, "考查一般过去时。are的过去式是were，am的过去式是was。")
cho(672, "Tom often ______ TV on Sundays. Today is Sunday. He ______ TV now.", ["is watching; is watching","watches; watches","watches; is watching","is watching; watches"], 2, "根据often, on Sundays判断为一般现在时；根据now判断为现在进行时。故答案选C。")
cho(673, "Kate ______ five hundred English words so far.", ["has learned","learned","is learning","learns"], 0, "有标志性词so far可知应为现在完成时have/has done。故选A。")
cho(674, "Listen! Tom ______ to music now.", ["listen","listens","is listening"], 2, "listen是现在进行时的时间标志词。Tom是一个人单数，谓语用be动词is。故选C。")
